import typing

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class UserState(pydantic.BaseModel):
    lastseen: typing.Optional[int]


class GetUserInfoResultsSchema(pydantic.BaseModel):
    firstName: str
    middleName: typing.Optional[str]
    lastName: str
    nick: typing.Optional[str]
    about: str
    avatarId: typing.Optional[str]
    official: typing.Optional[bool]
    mute: typing.Optional[bool]
    commonChats: typing.Optional[int]
    phone: typing.Optional[str]
    bot: typing.Optional[bool]
    userState: UserState


class GetUserInfoResponseSchema(BaseRapiResponseSchema):
    results: GetUserInfoResultsSchema


class Chat(pydantic.BaseModel):
    sn: str
    name: str
    stamp: str
    memberCount: int
    public: bool
    about: str


class GetIdInfoResultsSchema(pydantic.BaseModel):
    chat: typing.Optional[Chat] = None


class GetIdInfoResponseSchema(BaseRapiResponseSchema):
    results: GetIdInfoResultsSchema


class GetIdInfoBatchResponseSchema(BaseRapiResponseSchema):
    results: dict[str, dict]


class ContactsEditResponseSchema(BaseRapiResponseSchema): ...


class ContactsDeleteResponseSchema(BaseRapiResponseSchema): ...


class UserStateAlter(pydantic.BaseModel):
    lastseen: int
    state: str


class Entry(pydantic.BaseModel):
    sn: str
    userState: UserStateAlter


class GetUserLastSeenResultsSchema(pydantic.BaseModel):
    entries: list[Entry]


class GetUserLastSeenResponseSchema(BaseRapiResponseSchema):
    results: GetUserLastSeenResultsSchema


class Contact(pydantic.BaseModel):
    sn: str


class Person(pydantic.BaseModel):
    sn: str
    firstName: typing.Optional[str] = None
    middleName: typing.Optional[str] = None
    lastName: typing.Optional[str] = None
    friendly: typing.Optional[str] = None
    deleted: typing.Optional[bool] = None


class ContactsGetResultsSchema(pydantic.BaseModel):
    contacts: list[Contact]
    persons: list[Person]


class ContactsGetResponseSchema(BaseRapiResponseSchema):
    results: ContactsGetResultsSchema
